function DIRECT_SUM(C, D):
    result <- empty set
    for a in C:
        for b in D:
            result.add(concat(a, b))     # a||b in F_2^{m+n}
    return result

function LEFT_PART(z, m):  return z[0 .. m-1]
function RIGHT_PART(z, m): return z[m .. end]

# Membership criterion (Theorem 3.1):
function MEM_DIRECT_SUM(z, C, D, m):
    return LEFT_PART(z, m) in C and RIGHT_PART(z, m) in D

